<script setup>
import { Head, Link, useForm } from '@inertiajs/vue3';
import AuthLayout from '@/Layouts/AuthLayout.vue';
const form = useForm({ name: '', email: '', password: '', password_confirmation: '' });
const submit = () => form.post('/register', { onFinish: () => form.reset('password', 'password_confirmation') });
</script>
<template><Head title="Create account" /><AuthLayout title="Create your account" subtitle="Begin with a clear view of your investments."><form class="mt-7 space-y-5" @submit.prevent="submit"><div><label class="field-label" for="name">Name</label><input id="name" v-model="form.name" class="field" autocomplete="name" required><p v-if="form.errors.name" class="field-error" role="alert">{{ form.errors.name }}</p></div><div><label class="field-label" for="email">Email</label><input id="email" v-model="form.email" class="field" type="email" autocomplete="email" required><p v-if="form.errors.email" class="field-error" role="alert">{{ form.errors.email }}</p></div><div><label class="field-label" for="password">Password</label><input id="password" v-model="form.password" class="field" type="password" autocomplete="new-password" required><p v-if="form.errors.password" class="field-error" role="alert">{{ form.errors.password }}</p></div><div><label class="field-label" for="password_confirmation">Confirm password</label><input id="password_confirmation" v-model="form.password_confirmation" class="field" type="password" autocomplete="new-password" required></div><button class="btn btn-primary w-full" :disabled="form.processing" type="submit">Create account</button></form><p class="mt-6 text-sm text-slate-600">Already have an account? <Link href="/login">Sign in</Link></p></AuthLayout></template>
